import { useNavigate, useParams } from "react-router-dom";
import {
  useMarketResearchQuery,
  type JobsSnapshot,
} from "../features/marketResearch";
import { SnapshotSignalsReview } from "../features/marketSignals/components";
import { Button, EmptyState, PageShell } from "../shared/ui";

const MARKET_SIGNALS_PATH = "/upwork-dashboard/market-signals";

const MarketSignalReviewPage = () => {
  const navigate = useNavigate();
  const { researchId, snapshotId } = useParams();
  const researchQuery = useMarketResearchQuery(researchId);
  const research = researchQuery.data;
  const snapshots: JobsSnapshot[] = research?.snapshots ?? [];
  const snapshot = snapshots.find((item) => item.id === snapshotId);

  return (
    <PageShell>
      <div className="flex justify-start">
        <Button
          size="sm"
          variant="ghost"
          onClick={() => navigate(MARKET_SIGNALS_PATH)}
        >
          Back
        </Button>
      </div>

      {researchQuery.isLoading ? (
        <EmptyState title="Loading signals..." />
      ) : researchQuery.error ? (
        <EmptyState title="Unable to load review" />
      ) : research && snapshot ? (
        <SnapshotSignalsReview research={research} snapshot={snapshot} />
      ) : (
        <EmptyState title="Snapshot not found" />
      )}
    </PageShell>
  );
};

export default MarketSignalReviewPage;
