import { useQuery } from "@tanstack/react-query";
import { fetchMarketResearch } from "../api/marketResearchApi";
import type { MarketResearch } from "../types";
import { marketResearchKeys } from "./keys";

export const useMarketResearchQuery = (id?: string) =>
  useQuery<MarketResearch>({
    queryKey: id
      ? marketResearchKeys.detail(id)
      : [...marketResearchKeys.all, "detail", "disabled"],
    queryFn: ({ signal }) => fetchMarketResearch(id!, { signal }),
    enabled: Boolean(id),
    staleTime: 2 * 60 * 1000,
  });
